func qwen3RouteContractStats() map[string]int {
	stats := map[string]int{"total": len(qwen3RouteContracts), "covered": 0, "missing": 0, "high_risk": 0}
	for _, contract := range qwen3RouteContracts {
		if contract.CoveredByGo {
			stats["covered"]++
		} else {
			stats["missing"]++
		}
		if contract.RiskLevel == "high" || contract.RiskLevel == "critical" {
			stats["high_risk"]++
		}
	}
	return stats
}

func qwen3RouteContractsByDomain(domain string) []routeContract {
	out := []routeContract{}
	for _, contract := range qwen3RouteContracts {
		if contract.Domain == domain {
			out = append(out, contract)
		}
	}
	return out
}
